import{_ as o,o as a,c,a2 as d}from"./chunks/framework.Bg-Zxr5O.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/IF.md","filePath":"manual-zh/IF.md","lastUpdated":1785684581000}'),r={name:"manual-zh/IF.md"};function t(n,e,p,s,i,_){return a(),c("div",null,[...e[0]||(e[0]=[d(`<h3 id="_12-6-if" tabindex="-1">12.6 IF <a class="header-anchor" href="#_12-6-if" aria-label="Permalink to &quot;12.6 IF&quot;">​</a></h3><pre><code>IF condition variable=expression.
</code></pre><p>或</p><pre><code>IF condition vector(index)=expression.
</code></pre><p><code>IF</code> 转换根据测试表达式的真值，有条件地将目标表达式的值赋给目标变量。</p><p>在 <code>IF</code> 关键字后指定要测试的布尔值表达式（见 <a href="./Expressions">表达式</a>）。该表达式对每个个案求值。如果值为真，则计算表达式的值并赋给指定变量。如果值为假或缺失，则不执行任何操作。可以赋值数值和字符串变量。当字符串表达式的宽度与目标变量的宽度不同时，表达式的字符串结果会按需截断或在右侧用空格填充。表达式和变量的类型必须匹配。</p><p>目标变量可以指定为向量的元素（见 <a href="./VECTOR">VECTOR</a>）。在这种情况下，必须在向量名后的括号中指定向量索引表达式。索引表达式必须求值为数值，在向下舍入到最接近的整数后，是命名向量的有效索引。</p><p>使用 <code>IF</code> 赋给在 <code>LEAVE</code> 上指定的变量（见 <a href="./LEAVE">LEAVE</a>）会重置该变量的保留状态。因此，<code>LEAVE</code> 应在 <code>IF</code> 之后指定，而不是之前。</p><p>当 <code>IF</code> 在 <code>TEMPORARY</code>（见 <a href="./TEMPORARY">TEMPORARY</a>）之后指定时，不能使用 <code>LAG</code> 函数（见 <a href="./Miscellaneous-Functions#LAG">LAG</a>）。</p>`,9)])])}const E=o(r,[["render",t]]);export{f as __pageData,E as default};
